insert into public.secoes (id, tipo_laudo_id, codigo, titulo, ordem, condicional, condicao, texto_automatico_template) values
  ('b766dbb2-2d71-5c42-9bc2-91e99e9432ed', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'identificacao_perito', 'I — Identificação do(a) Perito(a) Judicial', 1, false, null, null),
  ('84e89eba-9e2a-53e4-886d-be2af82f81c3', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'identificacao_periciando', 'II — Identificação do(a) Periciando(a)', 2, false, null, null),
  ('da20050b-8945-5fde-b11d-72e6b5be9630', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'objeto_pericia_pontos_controvertidos', 'III — Objeto da Perícia e Pontos Controvertidos', 3, false, null, 'A presente perícia tem por objeto esclarecer {{pontos_periciais_investigar}}, nos limites definidos pelo Juízo.'),
  ('50178f94-6374-5fdd-b76a-b49614b83a49', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'metodologia_medico_pericial', 'IV — Metodologia Médico-Pericial', 4, false, null, 'O método empregado consistiu na integração entre dados processuais, clínicos, ocupacionais e funcionais, com análise etiológica e correlação técnico-científica entre a condição de saúde identificada, as exposições laborais demonstradas e suas repercussões.'),
  ('9994332f-9e5f-5d0e-817e-4fc8f5f7ed24', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'sintese_alegacoes_partes', 'V — Síntese das Alegações das Partes', 5, false, null, 'O(a) reclamante sustenta {{reclamante_alega}}. A(s) reclamada(s), por sua vez, sustenta(m) {{reclamada_sustenta}}. As alegações foram consideradas como hipóteses a serem confrontadas com os elementos objetivos da perícia.'),
  ('6396f80f-b73f-5d37-b41e-8f88eadfbb4a', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'documentos_analisados', 'VI — Documentos Analisados', 6, false, null, 'Foram analisados {{total_documentos}} documentos, totalizando {{total_paginas}} páginas. Foram considerados pertinentes {{categorias_principais}}. {{documentos_desconsiderados_motivo}}'),
  ('d37cf33c-e642-55cb-a007-ed154f72a70e', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'historia_clinica_condicao', 'VII — História Clínica da Condição em Análise', 7, false, null, null),
  ('4836bd88-5397-5e7f-b40c-750ea048ed38', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'antecedentes_fatores_extralaborais', 'VIII — Antecedentes e Fatores Extralaborais', 8, false, null, 'Foram identificados {{antecedentes_fatores}} com potencial participação etiológica ou modificadora do quadro, os quais foram ponderados na análise causal, sem presunção automática de exclusão ou confirmação do nexo laboral.'),
  ('ed0f61c2-c4ad-54ae-9c45-e5e49364ce75', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'historia_ocupacional_completa', 'IX — História Ocupacional Completa', 9, false, null, null),
  ('3e0e00e8-8651-597a-81d8-71fd2f14eec4', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'profissiografia_funcao', 'X — Profissiografia da Função Objeto da Demanda', 10, false, null, 'A função de {{funcao_efetivamente_exercida}} compreendia {{descricao_concreta_tarefas}}, com exposição a {{demandas_biomecanicas}} em frequência/intensidade {{frequencia_ciclos}}, elementos considerados na análise etiológica e funcional.'),
  ('40d0e596-d537-519e-8e23-26723ab52909', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'condicoes_organizacao_trabalho', 'XI — Condições e Organização do Trabalho', 11, false, null, null),
  ('36eb71f8-22d8-5481-8289-6eb05f2f1250', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'matriz_exposicao_riscos', 'XII — Matriz de Exposição a Riscos Ocupacionais', 12, false, null, null),
  ('ea374d8f-24b9-536f-bfb9-fbf541bccbab', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'acidente_trabalho', 'XIII — Acidente de Trabalho — Quando Aplicável', 13, false, null, null),
  ('ace7fef5-f94b-558f-900a-f6bb59dcf0a0', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'observacao_pericial_espontanea', 'XIV — Observação Pericial Espontânea', 14, false, null, null),
  ('ce31da6b-243e-5f00-ad8b-13dbc10630af', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'exame_clinico_geral', 'XV — Exame Clínico Geral', 15, false, null, null),
  ('fb21088b-0095-50ce-9496-fb4f31f846ba', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'exame_fisico_aparelhos_sistemas', 'XVI — Exame Físico por Aparelhos e Sistemas', 16, false, null, null),
  ('97db24e6-9a3a-5775-b6f3-ea528d10f0bf', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'exames_complementares', 'XVII — Exames Complementares', 17, false, null, null),
  ('3efa1e08-b6ce-5182-96b1-16441a8236d6', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'diagnostico_nosologico', 'XVIII — Diagnóstico Nosológico', 18, false, null, 'O exame pericial permite estabelecer o diagnóstico de {{diagnostico_principal_tabela}}, CID {{cid_principal_tabela}}, fundamentado em {{elementos_fundamentacao}}.'),
  ('cccd4b14-21db-5b77-bb74-a7493901d70e', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'analise_etiologica', 'XIX — Análise Etiológica', 19, false, null, null),
  ('7410b528-ae04-5bf7-902c-7930d9ab5dc2', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'matriz_analise_nexo_causal', 'XX — Matriz de Análise do Nexo Causal', 20, false, null, 'A análise dos critérios de exposição, temporalidade, plausibilidade biológica, compatibilidade clínico-ocupacional e fatores concorrentes {{permite_ou_nao_permite}} estabelecer relação causal entre {{agravo}} e {{trabalho}}.'),
  ('b2213e8d-bb33-53b7-9578-a85a43d74559', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'analise_concausalidade', 'XXI — Análise da Concausalidade', 21, false, null, 'O trabalho não se apresenta como causa exclusiva do agravo, porém {{atuou_ou_nao_atuou}} como fator {{papel_trabalho}}, caracterizando {{concausalidade_ou_ausencia}} sob a perspectiva médico-pericial.'),
  ('e65b7dac-6fed-591b-bfc0-26cc0d0e0ce1', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'necessidade_pericia_posto_trabalho', 'XXII — Necessidade de Perícia do Posto de Trabalho / Complementação', 22, false, null, 'Os elementos atuais são {{suficiencia_elementos}} para análise das condições de trabalho. Recomenda-se {{necessidade_complementacao}}, com o objetivo específico de esclarecer {{objetivo_tecnico_especifico_diligencia}}.'),
  ('ffd615c3-6371-50d4-96ba-c9e60f6e262d', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'avaliacao_danos_temporarios', 'XXIII — Avaliação dos Danos Temporários', 23, false, null, null),
  ('3429549c-5318-5946-8439-e5ce548be19b', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'avaliacao_danos_permanentes', 'XXIV — Avaliação dos Danos Permanentes', 24, false, null, null),
  ('afed002e-8e82-5841-94cd-3148e22d0d10', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'avaliacao_capacidade_laborativa', 'XXV — Avaliação da Capacidade Laborativa', 25, false, null, 'Na data da perícia, o(a) periciando(a) apresenta {{capacidade_atual}}, de grau {{grau}}, com repercussão sobre {{atividades_afetadas}}, em razão de {{condicao}}.'),
  ('03dea131-9b1b-56fd-9a9a-4ded6ccd89d0', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'avaliacao_funcional_capacidade_residual', 'XXVI — Avaliação Funcional e Capacidade Residual', 26, false, null, null),
  ('03013e2c-48bd-54f2-adb8-5f9e34791d14', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'prognostico_tratamento_reabilitacao', 'XXVII — Prognóstico, Tratamento e Reabilitação', 27, false, null, null),
  ('29d649eb-2b55-5aee-9511-31019390aefc', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'dano_estetico', 'XXVIII — Dano Estético — Quando Integrar o Objeto', 28, false, null, null),
  ('d3823c2f-edb2-576d-bcc5-95c22031c8f0', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'coerencia_consistencia_medico_pericial', 'XXIX — Coerência e Consistência Médico-Pericial', 29, false, null, null),
  ('1a6025d3-4aa4-56ea-827f-f0cc3b7d2342', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'discussao_medico_pericial', 'XXX — Discussão Médico-Pericial', 30, false, null, 'O(a) periciando(a) apresenta {{diagnostico_cid}}, demonstrado por {{elementos_demonstracao}}. A literatura reconhece como fatores etiológicos {{fatores_etiologicos_literatura}}. No caso concreto, foram identificadas exposições ocupacionais {{exposicoes_ocupacionais_descricao}}, com intensidade, frequência e duração {{intensidade_frequencia_duracao}}. A relação temporal entre exposição e adoecimento mostrou-se {{compatibilidade_temporal}}. Foram ainda identificados {{fatores_individuais_extralaborais}}. A integração desses elementos {{sustenta_ou_nao_sustenta}} participação do trabalho na gênese ou agravamento do quadro. As repercussões atuais consistem em {{danos_limitacoes}}, com impacto laboral {{impacto_laboral_descricao}}.'),
  ('6a142fc5-dcf4-5f7a-bfd8-3f55176ee6f1', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'respostas_quesitos', 'XXXI — Respostas aos Quesitos', 31, false, null, null),
  ('e6f0d257-1411-590a-a8e7-8ae39ede4209', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'conclusao_medico_pericial', 'XXXII — Conclusão Médico-Pericial', 32, false, null, null),
  ('121fe223-d6d0-5383-b5b8-7acb78060994', '06e11947-4ba1-530b-a888-bcfa9096df9e', 'encerramento', 'XXXIII — Encerramento', 33, false, null, 'O presente laudo representa o entendimento técnico desta Médica Perita Judicial, fundamentado nos elementos disponibilizados nos autos, informações colhidas durante a avaliação, exame clínico realizado, dados ocupacionais, literatura médico-científica pertinente e metodologia médico-pericial aplicada ao caso concreto. As conclusões restringem-se às questões médico-periciais submetidas à análise, sem atribuição de responsabilidade jurídica, culpa ou infração ética. Permanecendo esta profissional à disposição do Juízo para eventuais esclarecimentos.');
