  ('1fdc79e1-bbf2-5199-a030-8f622356075f', 'e6f0d257-1411-590a-a8e7-8ae39ede4209', null, 'conclusao_restricoes_adaptacoes', 'Restrições/adaptações', 'texto_livre', 10, false, true, null, null, false, null, false, null),
  ('acb4a58c-0eaf-5607-a6c8-4b918513475f', 'e6f0d257-1411-590a-a8e7-8ae39ede4209', null, 'conclusao_prognostico', 'Prognóstico', 'texto_livre', 11, false, true, null, null, false, null, false, null),
  ('7ad2ef4e-d524-5843-9034-70aa6aed1302', 'e6f0d257-1411-590a-a8e7-8ae39ede4209', null, 'conclusao_modelo_automatico', 'Modelo automático de conclusão', 'selecao_unica', 12, false, true, '[{"codigo": "sem_nexo_sem_incapacidade", "rotulo": "Sem nexo e sem incapacidade", "texto_automatico": "O(a) periciando(a) apresenta {{conclusao_diagnostico_principal}}, porém os elementos clínicos, documentais, ocupacionais e etiológicos analisados não demonstram relação causal ou concausal tecnicamente sustentada com o trabalho objeto da demanda. Na data da perícia, não se identificam limitações funcionais de magnitude suficiente para caracterizar incapacidade laborativa."}, {"codigo": "nexo_causal", "rotulo": "Nexo causal", "texto_automatico": "O conjunto médico-pericial demonstra diagnóstico de {{conclusao_diagnostico_principal}}, exposição ocupacional a {{fator_exposicao}}, compatibilidade temporal e biológica e coerência clínico-ocupacional suficientes para estabelecer nexo causal entre o agravo e o trabalho exercido. As repercussões atuais consistem em {{danos_limitacoes}}, com capacidade laborativa {{situacao_capacidade}}."}, {"codigo": "concausalidade", "rotulo": "Concausalidade", "texto_automatico": "A condição apresenta etiologia multifatorial, com participação de {{fatores_nao_laborais}}. Entretanto, as condições de trabalho demonstradas atuaram como fator {{papel_trabalho}}, caracterizando concausalidade médico-pericial. As repercussões funcionais atuais são {{descricao_repercussoes}}."}, {"codigo": "incapacidade_temporaria", "rotulo": "Incapacidade temporária", "texto_automatico": "O(a) periciando(a) apresenta limitação funcional temporária decorrente de {{condicao}}, incompatível atualmente com {{funcao_exigencias}}. Estima-se necessidade de {{tratamento_periodo}}, devendo a capacidade ser reavaliada conforme evolução clínica."}, {"codigo": "reducao_permanente_capacidade", "rotulo": "Redução permanente da capacidade", "texto_automatico": "Há sequela consolidada com redução funcional permanente para {{tarefas_funcao}}, permanecendo capacidade residual para {{atividades_residuais}}, mediante {{restricoes_adaptacoes}}."}]'::jsonb, null, false, null, true, null),
